#include <bits/stdc++.h>
using namespace std;
int main(){int n; long long T; scanf("%d %lld",&n,&T);
 vector<long long> dp(T+1,0); dp[0]=1; const long long MOD=1000000007LL;
 for(int i=0;i<n;i++){ long long v; scanf("%lld",&v);
  for(long long s=T; s>=v; s--){ dp[s]=(dp[s]+dp[s-v])%MOD; } }
 printf("%lld\n", dp[T]); return 0;}
